const OPPOSED_FORM = -0.5;
const OPPOSED_HOLD = -0.2;
/** 枠の形をこの秒数だけ保つと、枠が出る。手を動かす途中で一瞬その形になっただけでは出さない。 */
const FORM_DELAY = 0.35;
/**
