  private time = 0;
  private lastVideoTime = 0;
  private videoAdvancedAt = -Infinity;

  constructor(private readonly app: App) {
    // Color は内部でリニアに直されるので、シェーダーに渡す sRGB の値を取り直す。
    BACKDROP.getRGB(_clearColor, THREE.SRGBColorSpace);
